// ACPlayerCharacter::SetupPlayerInputComponent
// 设置玩家的输入组件
// 参数: PlayerInputComponent - 玩家的输入组件指针
void ACPlayerCharacter::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)
{
	// 调用基类的SetupPlayerInputComponent函数
	Super::SetupPlayerInputComponent(PlayerInputComponent);

	// 尝试将输入组件转换为UEnhancedInputComponent类型
	if (UEnhancedInputComponent* EnhancedInputComponent = CastChecked<UEnhancedInputComponent>(PlayerInputComponent))
	{
		// 绑定跳跃动作，当触发事件发生时调用Jump函数
		EnhancedInputComponent->BindAction(JumpInputAction, ETriggerEvent::Triggered, this, &ACPlayerCharacter::Jump);
		// 绑定视线输入动作，当触发事件发生时调用HandleLookInput函数
		EnhancedInputComponent->BindAction(LookInputAction, ETriggerEvent::Triggered, this, &ACPlayerCharacter::HandleLookInput);
		// 绑定移动输入动作，当触发事件发生时调用HandleMoveInput函数
		EnhancedInputComponent->BindAction(MoveInputAction, ETriggerEvent::Triggered, this, &ACPlayerCharacter::HandleMoveInput);
	}
}
```

