    GetCharacterMovement()->bOrientRotationToMovement = !bIsAiming;

    // 调用瞄准状态改变事件通知其他系统
    OnAimStateChanged(bIsAiming);
}

void ACCharacter::SetIsAiming(bool bIsAiming)
{
	bUseControllerRotationYaw = bIsAiming;
	GetCharacterMovement()->bOrientRotationToMovement = !bIsAiming;
	OnAimStateChanged(bIsAiming);
}

