/** * Gets the time remaining before the specified timer is called. * * @param InHandle The handle of the timer to check the remaining time of. * @return The current time remaining, or -1.f if timer does not exist. * * This function calculates the time remaining until the timer triggers its callback function. * If the timer does not exist, it returns -1.f. */ FORCEINLINE float GetTimerRemaining(FTimerHandle InHandle) const { FTimerData const* const TimerData = FindTimer(InHandle); return InternalGetTimerRemaining(TimerData); }
