// 创建一个等待目标数据的任务实例
// 参数说明:
// - this: 当前能力任务的上下文对象(UGA_GroundBlast实例)
// - NAME_None: 目标数据名称(使用默认名称)
// - EGameplayTargetingConfirmation::UserConfirmed: 目标确认方式为玩家手动确认
// - TargetActorClass: 目标Actor的类类型
UAbilityTask_WaitTargetData* WaitTargetDataTask = UAbilityTask_WaitTargetData::WaitTargetData(this, NAME_None, EGameplayTargetingConfirmation::UserConfirmed, TargetActorClass);

// 绑定有效数据回调函数 - 当获得有效目标数据时调用UGA_GroundBlast::TargetConfirmed方法
WaitTargetDataTask->ValidData.AddDynamic(this, &UGA_GroundBlast::TargetConfirmed);

// 绑定取消回调函数 - 当目标选择被取消时调用UGA_GroundBlast::TargetCanceled方法
WaitTargetDataTask->Cancelled.AddDynamic(this, &UGA_GroundBlast::TargetCanceled);

// 激活任务，开始等待目标数据
WaitTargetDataTask->ReadyForActivation();
